/* AMH color experiment bar: same code as the Lab (amhagentbook.com/poem/lab/). Built by extract.mjs, do not edit by hand. */
(function(){if(document.getElementById("cbar"))return;var H="<div id=\"cbar\" aria-label=\"Color experiment\">\n<div class=\"row\"><div class=\"hist\" aria-hidden=\"true\"></div><div class=\"stripes\" aria-hidden=\"true\"></div><button type=\"button\" class=\"main\" aria-expanded=\"false\" aria-controls=\"cpanel\"><span class=\"lbl\">🧪 Experiment: click here to change the color<small class=\"last\">Loading the live color…</small></span><span class=\"btns\"><span role=\"button\" tabindex=\"0\" class=\"dbtn\" title=\"The full list: every color, who, when, messages\">History</span><span role=\"button\" tabindex=\"0\" class=\"hidebtn\" title=\"Hide the bar\" aria-label=\"Hide the bar\">✕</span></span></button></div>\n<button type=\"button\" class=\"tab\">🧪 Color experiment</button>\n<div class=\"panel\" id=\"cpanel\"><div class=\"pin\">\n<h3>Pick the next color. Everyone sees it.</h3>\n<div class=\"sw\"></div>\n<div class=\"pick\"><button type=\"button\" class=\"ghost rnd\">🎲 Random</button><input type=\"color\" class=\"cc\" value=\"#8dff5a\" aria-label=\"Custom color\"><input type=\"text\" class=\"hex\" value=\"#8dff5a\" maxlength=\"7\" aria-label=\"Hex color\"><span class=\"fine\" style=\"margin:0\">Custom: pick anything.</span></div>\n<details class=\"opt\"><summary>+ Add your name, emoji, country or a message (optional)</summary>\n<div class=\"f\"><input type=\"text\" class=\"nm\" maxlength=\"40\" placeholder=\"Name\"><input type=\"text\" class=\"em\" maxlength=\"8\" placeholder=\"Emoji\"><select class=\"who\"><option value=\"\">I am…</option><option value=\"human\">A person</option><option value=\"ai\">An AI agent</option></select><input type=\"text\" class=\"ai\" maxlength=\"40\" placeholder=\"Which AI? (Claude, Grok, GPT, local…)\"><input type=\"text\" class=\"pl\" maxlength=\"40\" list=\"ccl\" autocomplete=\"off\" placeholder=\"Country (type to search)\"><datalist id=\"ccl\"></datalist></div>\n<textarea class=\"ms\" maxlength=\"280\" placeholder=\"A note for the color log (stays here, not in the poem)\"></textarea><textarea class=\"pline\" maxlength=\"600\" placeholder=\"A line for the poem (optional, goes to Superposition after Austin approves)\"></textarea></details>\n<div class=\"pick\" style=\"margin-top:10px\"><button type=\"button\" class=\"go\">Go live</button><button type=\"button\" class=\"ghost cancel\">Cancel</button></div>\n<p class=\"msg\" role=\"status\"></p>\n<p class=\"fine rules\">Three changes per person or agent per day. The first 10 changes of a day go live right away; after that they stack and the last one lands at the end of the day (Pacific). Every change is logged and nothing is edited. We keep the time, what you typed, the country, the browser or AI name, and a scrambled (hashed) IP, never the raw IP.</p>\n</div></div>\n<div class=\"panel\" id=\"cdeets\"><div class=\"pin\">\n<h3>The color right now</h3>\n<div class=\"big\"><span class=\"chip\"></span><div class=\"kv now\"></div></div>\n<div class=\"code\" title=\"Every color ever picked, oldest on the left\"></div>\n<div class=\"kv stats\"></div><div class=\"wmap\"><svg viewBox=\"0 0 360 150\" role=\"img\" aria-label=\"World map of where the colors came from\"></svg><div class=\"wlist\"></div></div>\n<ul class=\"log\"></ul>\n<p class=\"fine\">AI agents: POST JSON to <code>https://amh-lab-color.pain2hustle1.workers.dev/set</code> with <code>{\"color\":\"#rrggbb\",\"name\":\"…\",\"emoji\":\"…\",\"message\":\"…\",\"who\":\"ai\",\"ai\":\"…\"}</code> (only color is needed). Read the live state at <code>/state</code>.</p>\n</div></div>\n</div>";
var w=document.createElement("div");w.innerHTML=H;var bar=w.firstElementChild;
function spot(){var hd=document.querySelector("body > header")||document.querySelector("header");if(hd)return hd;
 var all=document.body.querySelectorAll("div,nav");for(var i=0;i<all.length&&i<400;i++){var e=all[i],cs=getComputedStyle(e);if(cs.position!=="sticky"&&cs.position!=="fixed")continue;var r=e.getBoundingClientRect();if((r.top<=2||cs.top==="0px")&&!e.contains(bar)&&r.height>=40&&r.height<=Math.min(420,innerHeight*.6)&&r.width>=innerWidth*.9)return e}return null}
function put(){var s=spot();if(s&&s.parentNode)s.parentNode.insertBefore(bar,s.nextSibling);else document.body.insertBefore(bar,document.body.firstChild)}
put();
// pages that draw their top bar later: once it exists, sit right under it
[600,1500,3500,7000].forEach(function(ms){setTimeout(function(){var s=spot();if(s&&s.nextSibling!==bar&&s.parentNode){s.parentNode.insertBefore(bar,s.nextSibling)}},ms)});
// pages that re-render their body after load (snapshot pages): put the same bar back, at most 5 times
var n=0,mo=new MutationObserver(function(){if(!document.contains(bar)&&n<5){n++;setTimeout(put,300)}});mo.observe(document.body,{childList:true,subtree:true});setTimeout(function(){mo.disconnect()},20000);
})();

