$(".rnd").onclick=function(){setPick("#"+("00000"+Math.floor(Math.random()*16777216).toString(16)).slice(-6))};
cc.oninput=function(){setPick(cc.value)};hex.oninput=function(){var v=hex.value.trim();if(v[0]!=="#")v="#"+v;if(/^#[0-9a-fA-F]{6}$/.test(v))setPick(v)};
