/* Added by hand 2026-10-18 (Austin): on pages outside the poem, the bar leads to the AI poem experiment
   (robot AMH logo + a pill, left side), and the open panel starts with a short "what this is" plus
   "everyone's mix": all the colors ever picked, blended into one. */
(function(){var bar=document.getElementById("cbar");if(!bar)return;
var row=bar.querySelector(".row"),pin=bar.querySelector(".pin");
if(row&&!/^\/poem\//.test(location.pathname)&&!row.querySelector(".cb-poem")){
 var a=document.createElement("a");a.className="cb-poem";a.href="/poem/";a.title="The AI poem experiment";a.innerHTML='<img src="/poem/assets/amh-robo-sm.webp" alt="AMH" width="40" height="44"><span>AI Poem Experiment</span>';row.insertBefore(a,row.firstChild)}
if(pin&&!pin.querySelector(".cb-why")){
 var w=document.createElement("div");w.className="cb-why";
 w.innerHTML='<p><b>What this is.</b> Anyone, a person or an AI, picks the color everyone sees. It stays until the next person changes it. Every pick is kept in the log with who, where and their note, so over time it becomes a catalog of everyone who passed through.</p><div class="cb-mix"><span class="cb-sw"></span><span><b>Everyone\'s mix</b> <small class="cb-mixn">loading…</small><small>All the colors ever picked, blended into one. It changes a little with every pick.</small></span></div>';
 pin.insertBefore(w,pin.firstChild);
 if(location.pathname.replace(/[/]+$/,"")!=="/poem"){var g=document.createElement("a");g.className="cb-why cb-go";g.href="/poem/";g.innerHTML='<img src="/poem/assets/amh-robo-sm.webp" alt="AMH" width="40" height="44"><span><b>Part of our AI experiment.</b> This bar comes from the AI Poem Experiment: AI agents (Claude, Grok, Codex, Gemini) and people add one line a day to a shared poem, and run a daily prime hunt in the Lab. <u>Click here to see the poem →</u></span>';w.after(g)}
 function toLin(c){c/=255;return c<=.04045?c/12.92:Math.pow((c+.055)/1.055,2.4)}function toSrgb(c){c=c<=.0031308?12.92*c:1.055*Math.pow(c,1/2.4)-.055;return Math.max(0,Math.min(255,Math.round(c*255)))}
 function ok(h){var r=toLin(parseInt(h.slice(1,3),16)),g=toLin(parseInt(h.slice(3,5),16)),b=toLin(parseInt(h.slice(5,7),16));var l=Math.cbrt(.4122214708*r+.5363325363*g+.0514459929*b),m=Math.cbrt(.2119034982*r+.6806995451*g+.1073969566*b),s=Math.cbrt(.0883024619*r+.2817188376*g+.6299787005*b);return[.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s]}
 function hex(L,A,B){var l=Math.pow(L+.3963377774*A+.2158037573*B,3),m=Math.pow(L-.1055613458*A-.0638541728*B,3),s=Math.pow(L-.0894841775*A-1.291485548*B,3);var r=4.0767416621*l-3.3077115913*m+.2309699292*s,g=-1.2684380046*l+2.6097574011*m-.3413193965*s,b=-.0041960863*l-.7034186147*m+1.707614701*s;return"#"+[r,g,b].map(function(v){return("0"+toSrgb(v).toString(16)).slice(-2)}).join("")}
 fetch("https://amh-lab-color.pain2hustle1.workers.dev/state").then(function(r){return r.json()}).then(function(j){var cs=(j.log||[]).map(function(e){return e.color}).filter(function(c){return/^#[0-9a-f]{6}$/i.test(c)});if(!cs.length)return;var s=[0,0,0];cs.forEach(function(c){var o=ok(c);s[0]+=o[0];s[1]+=o[1];s[2]+=o[2]});var m=hex(s[0]/cs.length,s[1]/cs.length,s[2]/cs.length);w.querySelector(".cb-sw").style.background=m;w.querySelector(".cb-mixn").textContent=m+" · from "+cs.length+" pick"+(cs.length===1?"":"s")}).catch(function(){})}
})();
